garbage-collection.pseudocode:
def mark(roots):  # 루트에서 도달 가능한 객체 표시
    stack = list(roots)
    while stack:
        obj = stack.pop()
        if not obj.marked:
            obj.marked = True
            stack.extend(obj.refs)  # 참조 대상 계속 추적

def sweep(heap):  # 표시 안 된 객체 회수
    for obj in list(heap):
        if obj.marked:
            obj.marked = False  # 다음 GC를 위해 초기화
        else:
            heap.remove(obj)  # 도달 불가 → 메모리 해제

def collect(roots, heap):
    mark(roots)  # Stop-the-World 구간
    sweep(heap)

gaussian-quadrature.pseudocode:
def gauss_legendre_2pt(f, a, b):
    nodes = [-1 / sqrt(3), 1 / sqrt(3)]  # P2(x)의 근
    weights = [1.0, 1.0]
    mid, half = (a + b) / 2, (b - a) / 2  # [-1,1] → [a,b]
    return half * sum(w * f(mid + half * x)
                      for x, w in zip(nodes, weights))

# 2점으로 3차 다항식까지 정확
# gauss_legendre_2pt(lambda x: x ** 3, 0, 2) ≈ 4.0
